def algorithm(func, dim, lb, ub, budget, rng):
    def sample(rng, n, lb, ub):
        return rng.uniform(lb, ub, size=(n, dim))

    def clip(x, lb, ub):
        return np.minimum(np.maximum(x, lb), ub)

    x = sample(rng, 1, lb, ub)
    sigma = (ub - lb) / 3.0
    step_size = 1e-6

    for _ in range(budget):
        y = clip(func(x), float('-inf'), float('inf'))
        if np.isnan(y).any():
            x = sample(rng, 1, lb, ub)
            continue
        sigma = sigma * (1 + rng.normal(0, 0.01) / rng.normal(0, 0.01))
        step_size = sigma * rng.normal(0, 1)

        for _ in range(int(budget / 5)):
            x_new = clip(x + step_size * rng.normal(0, 1, size=dim), lb, ub)
            y_new = func(x_new)
            if np.isnan(y_new):
                continue
            if y_new < y:
                y = y_new
                x = x_new

    return x

def algorithm(func, dim, lb, ub, budget, rng):
    def Rosenbrock(x):
        return func(x)

    def clip(candidate):
        clipped_candidate = np.clip(candidate, a_min=lb, a_max=ub)
        return clipped_candidate

    x_best = 1.0 * np.ones(dim)  # Initialize the best solution
    f_best = float('inf')  # Initialize the best objective value

    for _ in range(budget):
        # Differential Evolution (DE) part
        x_new = x_best + rng.uniform(-2, 2, size=dim)
        x_clipped = clip(x_new)
        f_value = Rosenbrock(x_clipped)

        if f_value < f_best:
            f_best = f_value
            x_best = x_clipped

        # Simulated Annealing (SA) part
        acceptance_probability = 0.8  # Decrease this value to increase exploitation and decrease exploration
        delta_f = f_value - f_best

        if delta_f < 0:
            x_best = x_clipped
        else:
            probability = np.exp(-delta_f / (budget * rng.uniform(1e-4, 1e-3)))
            if rng.random() < probability * acceptance_probability:
                x_best = x_clipped

    return x_best
